import type { Accessory, AlienLook, EyeVariant, MouthVariant, Outfit, PatternVariant, SpecialVariant } from "@/lib/types";

/**
 * FREAKTOPIA alien identity catalog. Every part is original layered SVG (components/art/Alien.tsx),
 * so any combination is valid and nothing is generated by an image API.
 * Bump ALIEN_ASSET_VERSION when the meaning of a stored part changes; stored aliens keep their version.
 */
export const ALIEN_ASSET_VERSION = 1;

export const FAMILIES = ["slime", "fuzz", "mutant", "jelly"] as const;
export type AlienFamily = (typeof FAMILIES)[number];

export const BODY_COLORS = {
  lime: "#B6F05C",
  violet: "#A276E9",
  coral: "#FF625C",
  sky: "#55BCEB",
  tangerine: "#FFAD5B",
  bubblegum: "#FF8FD1",
  mint: "#5CF0C8",
  lemon: "#F5E15C",
  cream: "#F5F2EA",
  ruby: "#E0475B",
} as const;
export type BodyColor = keyof typeof BODY_COLORS;
export const COLOR_KEYS = Object.keys(BODY_COLORS) as BodyColor[];

export const EYES: EyeVariant[] = ["duo", "cyclops", "trio", "stalks", "sleepy", "star"];
export const MOUTHS: MouthVariant[] = ["grin", "fangs", "tongue", "zigzag", "o", "smirk"];
export const PATTERNS: PatternVariant[] = ["none", "spots", "stripes", "stars", "glitter", "swirl"];
export const SPECIALS: SpecialVariant[] = ["none", "blush", "freckles", "bandage", "glow", "drip"];
/** Accessories a new alien can be born with, and that the owner may switch between later. */
export const BASE_ACCESSORIES: Accessory[] = ["none", "headphones", "shades", "antenna", "cap", "horns", "halo", "flower"];
/** Earned cosmetics: never part of a random roll. */
export const EARNED_ACCESSORIES: Accessory[] = ["crown", "dao_antenna"];
export const OUTFITS: Outfit[] = ["none", "hoodie", "jacket", "vest", "kimono"];

const NAME_A = ["ZOR", "BLIP", "GLOO", "FUZ", "MOK", "QUA", "ZIB", "NUB", "WUB", "PLOO", "KRAK", "SQUI", "VOO", "JIB", "DRO", "YIP"];
const NAME_B = ["BO", "ZZ", "PLE", "MO", "NK", "RP", "XY", "LO", "BIX", "DOO", "GA", "TRON"];

export interface AlienTraits {
  name: string;
  family: AlienFamily;
  bodyColor: BodyColor;
  accentColor: BodyColor;
  eyes: EyeVariant;
  mouth: MouthVariant;
  pattern: PatternVariant;
  accessory: Accessory;
  outfit: Outfit;
  outfitColor: BodyColor;
  special: SpecialVariant;
}

export interface AlienIdentity extends AlienTraits {
  userId: string;
  seed: string;
  assetVersion: number;
  createdAt: string;
}

export function toLook(a: Pick<AlienTraits, "family" | "bodyColor" | "accentColor" | "eyes" | "mouth" | "pattern" | "accessory" | "outfit" | "outfitColor" | "special">): AlienLook {
  return {
    species: a.family,
    body: BODY_COLORS[a.bodyColor],
    accent: BODY_COLORS[a.accentColor],
    outfit: a.outfit,
    outfitColor: BODY_COLORS[a.outfitColor],
    accessory: a.accessory,
    eyes: a.eyes,
    mouth: a.mouth,
    pattern: a.pattern,
    special: a.special,
  };
}

/**
 * Derives every trait from a seed. The seed itself comes from crypto.randomBytes on the server
 * (lib/alien/generate.ts); deriving from it keeps an alien reproducible and auditable.
 * `pick(i, n)` reads 32 bits of an HMAC-free hash stream: deterministic, uniform enough for 6–16 options.
 */
export function traitsFromSeed(seed: string, hash: (input: string) => Uint8Array): AlienTraits {
  const bytes = hash(seed);
  let i = 0;
  const pick = <T,>(list: readonly T[]) => {
    const v = ((bytes[i % bytes.length] << 8) | bytes[(i + 1) % bytes.length]) >>> 0;
    i += 2;
    return list[v % list.length];
  };
  const family = pick(FAMILIES);
  const bodyColor = pick(COLOR_KEYS);
  const accentColor = pick(COLOR_KEYS.filter((c) => c !== bodyColor));
  const eyes = pick(EYES);
  const mouth = pick(MOUTHS);
  // "none" is more common than any one pattern/special, so most aliens stay readable.
  const pattern = pick([...PATTERNS, "none", "none"] as PatternVariant[]);
  const special = pick([...SPECIALS, "none", "none", "none"] as SpecialVariant[]);
  const accessory = pick(BASE_ACCESSORIES);
  const outfit = pick(OUTFITS);
  const outfitColor = pick(COLOR_KEYS.filter((c) => c !== bodyColor));
  const name = `${pick(NAME_A)}${pick(NAME_B)}-${(((bytes[30] << 8) | bytes[31]) % 90) + 10}`;
  return { name, family, bodyColor, accentColor, eyes, mouth, pattern, accessory, outfit, outfitColor, special };
}

/** What the owner may change after birth. Family, colours, face, pattern and special are permanent (no reroll). */
export interface AlienCosmeticsPatch {
  outfit?: Outfit;
  outfitColor?: BodyColor;
  accessory?: Accessory;
}

export function validateCosmetics(p: AlienCosmeticsPatch, owned: Accessory[] = []): string | null {
  if (p.outfit !== undefined && !OUTFITS.includes(p.outfit)) return "outfit";
  if (p.outfitColor !== undefined && !COLOR_KEYS.includes(p.outfitColor)) return "outfitColor";
  if (p.accessory !== undefined && !BASE_ACCESSORIES.includes(p.accessory) && !owned.includes(p.accessory)) return "accessory";
  return null;
}
